head.script:
scwin.trigger1_onclick = function(e) {
    checkbox1.checkAll();
};
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById('checkbox1_label').innerText == '전체선택' || WebSquare.wUnit.getDomById('checkbox1_label').innerText == 'choose all';
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 allOption 을 확인한다.
    //1. Check allOption in the Source tab.
    //Verify step 1. allOption = "true"
    //Test step 2. displayAllOptionLabel 을 확인한다.
    //2. Check displayAllOptionLabel.
    //Verify step 2. displayAllOptionLabel = "true"
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('checkbox1_label').innerText == ''", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Test step 3. 브라우저에서 checkAll() 버튼을 클릭한다.
    //3. In your browser, click the checkAll () button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 3. Select all.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 28-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
